package com.asmj.marketplace.service.service;
import com.asmj.marketplace.service.controller.ServiceDtos.*;import com.asmj.marketplace.service.model.*;import com.asmj.marketplace.service.repository.*;import com.asmj.marketplace.user.model.User;import com.asmj.marketplace.user.repository.UserRepository;import com.asmj.marketplace.vendor.model.Vendor;import com.asmj.marketplace.vendor.repository.VendorRepository;import com.asmj.marketplace.notification.service.NotificationService;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import java.time.*;import java.util.*;
@Service @RequiredArgsConstructor public class ServiceMarketplaceService{
 final ServiceListingRepository services;final ProviderScheduleRepository schedules;final ServiceBookingRepository bookings;final UserRepository users;final VendorRepository vendors;final NotificationService notifications;
 public List<ServiceListing> publicServices(){return services.findByActiveTrueAndApprovedTrueOrderByCreatedAtDesc();}
 public List<ServiceListing> vendorServices(String email){return services.findByVendorIdOrderByCreatedAtDesc(vendor(email).getId());}
 public ServiceListing save(String email,ServiceRequest r,String id){Vendor v=vendor(email);ServiceListing s=id==null?ServiceListing.builder().vendorId(v.getId()).createdAt(Instant.now()).approved(false).active(false).build():services.findById(id).orElseThrow();if(!Objects.equals(s.getVendorId(),v.getId()))throw new IllegalArgumentException("Not your service");if(r.name()==null||r.name().isBlank())throw new IllegalArgumentException("Service name is required");s.setName(r.name().trim());s.setDescription(r.description());s.setCategoryId(r.categoryId());s.setServiceMode(r.serviceMode()==null?"AT_CUSTOMER":r.serviceMode());s.setImages(r.images()==null?new ArrayList<>():r.images());s.setServiceAreas(r.serviceAreas()==null?new ArrayList<>():r.serviceAreas());s.setSlotDurationMinutes(Math.max(15,r.slotDurationMinutes()));s.setBufferMinutes(Math.max(0,r.bufferMinutes()));s.setMaxBookingsPerSlot(Math.max(1,r.maxBookingsPerSlot()));s.setTaxRate(Math.max(0,r.taxRate()));s.setCommissionRate(Math.max(0,r.commissionRate()));s.setFeatured(r.featured());s.setCancellationPolicy(ServiceListing.CancellationPolicy.builder().freeCancellationHours(Math.max(0,r.freeCancellationHours())).cancellationFeePercent(Math.max(0,Math.min(100,r.cancellationFeePercent()))).build());List<ServiceListing.Package> ps=new ArrayList<>();if(r.packages()!=null)for(PackageRequest p:r.packages())ps.add(ServiceListing.Package.builder().id(p.id()==null||p.id().isBlank()?UUID.randomUUID().toString():p.id()).name(req(p.name(),"Package name required")).description(p.description()).price(Math.max(0,p.price())).durationMinutes(Math.max(15,p.durationMinutes())).active(p.active()).build());if(ps.isEmpty())ps.add(ServiceListing.Package.builder().id(UUID.randomUUID().toString()).name("Standard").price(0).durationMinutes(s.getSlotDurationMinutes()).active(true).build());s.setPackages(ps);s.setUpdatedAt(Instant.now());return services.save(s);}
 public List<ProviderSchedule> schedules(String email){return schedules.findByVendorIdOrderByDayOfWeekAscStartTimeAsc(vendor(email).getId());}
 public ProviderSchedule saveSchedule(String email,ScheduleRequest r,String id){Vendor v=vendor(email);ServiceListing s=services.findById(r.serviceId()).orElseThrow();if(!Objects.equals(s.getVendorId(),v.getId()))throw new IllegalArgumentException("Not your service");if(!r.startTime().isBefore(r.endTime()))throw new IllegalArgumentException("Schedule start must be before end");ProviderSchedule x=id==null?ProviderSchedule.builder().vendorId(v.getId()).build():schedules.findById(id).orElseThrow();x.setServiceId(s.getId());x.setDayOfWeek(r.dayOfWeek());x.setStartTime(r.startTime());x.setEndTime(r.endTime());x.setActive(r.active());return schedules.save(x);}
 public ServiceBooking create(String email,BookingRequest r){User u=user(email);ServiceListing s=services.findById(r.serviceId()).orElseThrow();if(!s.isActive()||!s.isApproved())throw new IllegalArgumentException("Service unavailable");if(r.serviceDate()==null||r.startTime()==null)throw new IllegalArgumentException("Date and time are required");if(r.serviceDate().isBefore(LocalDate.now())||r.serviceDate().isEqual(LocalDate.now())&&r.startTime().isBefore(LocalTime.now()))throw new IllegalArgumentException("Service date/time must be in the future");if(r.address()==null||r.address().isBlank())throw new IllegalArgumentException("Service address is required");ServiceListing.Package p=s.getPackages().stream().filter(x->x.isActive()&&Objects.equals(x.getId(),r.packageId())).findFirst().orElseGet(()->s.getPackages().stream().filter(ServiceListing.Package::isActive).findFirst().orElseThrow());LocalTime end=r.startTime().plusMinutes(p.getDurationMinutes());ProviderSchedule sch=schedules.findByServiceIdAndDayOfWeekAndActiveTrue(s.getId(),r.serviceDate().getDayOfWeek()).stream().filter(x->!r.startTime().isBefore(x.getStartTime())&&!end.isAfter(x.getEndTime())).findFirst().orElseThrow(()->new IllegalArgumentException("Selected time is outside provider working hours"));List<String> blocking=List.of("REQUESTED","PROVIDER_CONFIRMED","CUSTOMER_CONFIRMED","PROVIDER_EN_ROUTE","SERVICE_STARTED","SERVICE_IN_PROGRESS");long overlap=bookings.findByServiceIdAndServiceDateAndStatusIn(s.getId(),r.serviceDate(),blocking).stream().filter(b->overlap(b.getStartTime(),b.getEndTime(),r.startTime(),end)).count();if(overlap>=s.getMaxBookingsPerSlot())throw new IllegalArgumentException("No availability for this time slot");if(s.getBufferMinutes()>0){LocalTime before=r.startTime().minusMinutes(s.getBufferMinutes()),after=end.plusMinutes(s.getBufferMinutes());boolean buffered=bookings.findByServiceIdAndServiceDateAndStatusIn(s.getId(),r.serviceDate(),blocking).stream().anyMatch(b->overlap(b.getStartTime(),b.getEndTime(),before,after));if(buffered)throw new IllegalArgumentException("Provider buffer time makes this slot unavailable");}
 double base=p.getPrice(),tax=base*s.getTaxRate()/100,discount=0,total=base+tax;Instant now=Instant.now();Vendor v=vendors.findById(s.getVendorId()).orElseThrow();ServiceBooking b=ServiceBooking.builder().bookingNumber("ASMJ-S"+String.format("%08d",Math.abs(UUID.randomUUID().hashCode()))).serviceId(s.getId()).vendorId(v.getId()).customerId(u.getId()).serviceName(s.getName()).packageId(p.getId()).packageName(p.getName()).serviceDate(r.serviceDate()).startTime(r.startTime()).endTime(end).customerName(req(r.customerName()==null?u.getName():r.customerName(),"Customer name required")).customerMobile(r.customerMobile()==null?u.getMobile():r.customerMobile()).address(req(r.address(),"Service address required")).city(req(r.city(),"Service city is required")).landmark(r.landmark()).notes(r.notes()).status("REQUESTED").baseAmount(base).taxAmount(tax).discountAmount(discount).totalAmount(total).discountCode(r.discountCode()).commissionAmount(base*s.getCommissionRate()/100).statusHistory(new ArrayList<>()).completionNotes(new ArrayList<>()).createdAt(now).updatedAt(now).build();b.getStatusHistory().add(entry("REQUESTED",u.getId(),"Service booking requested",now));ServiceBooking saved=bookings.save(b);notifications.create(v.getUserId(),"New service booking",saved.getBookingNumber()+" requested for "+saved.getServiceDate()+" at "+saved.getStartTime(),"SERVICE_BOOKING");return saved;}
 boolean overlap(LocalTime a,LocalTime b,LocalTime c,LocalTime d){return a.isBefore(d)&&c.isBefore(b);}
 public List<ServiceBooking> my(String email){return bookings.findByCustomerIdOrderByCreatedAtDesc(user(email).getId());}public List<ServiceBooking> vendorBookings(String email){return bookings.findByVendorIdOrderByCreatedAtDesc(vendor(email).getId());}
 public ServiceBooking status(String email,String id,StatusRequest r){ServiceBooking b=bookings.findById(id).orElseThrow();User u=user(email);boolean admin=u.getRoles().contains(User.Role.ADMIN);String vendorId=vendors.findByUserId(u.getId()).map(Vendor::getId).orElse(null);if(!admin&&!Objects.equals(vendorId,b.getVendorId())&&!Objects.equals(u.getId(),b.getCustomerId()))throw new IllegalArgumentException("Not authorized");validate(b.getStatus(),r.status());if("CANCELLED".equals(r.status())&&Objects.equals(u.getId(),b.getCustomerId())){ServiceListing s=services.findById(b.getServiceId()).orElse(null);if(s!=null&&s.getCancellationPolicy()!=null){long hours=Duration.between(Instant.now(),b.getServiceDate().atTime(b.getStartTime()).atZone(ZoneId.systemDefault()).toInstant()).toHours();if(hours<s.getCancellationPolicy().getFreeCancellationHours()){double fee=b.getBaseAmount()*s.getCancellationPolicy().getCancellationFeePercent()/100;b.setCancellationFeeAmount(fee);b.setRefundAmount(Math.max(0,b.getTotalAmount()-fee));}else b.setRefundAmount(b.getTotalAmount());}}b.setStatus(r.status());Instant now=Instant.now();b.getStatusHistory().add(entry(r.status(),u.getId(),r.note(),now));b.setUpdatedAt(now);ServiceBooking saved=bookings.save(b);String target=Objects.equals(u.getId(),b.getCustomerId())?b.getVendorId():b.getCustomerId();Vendor vv=vendors.findById(b.getVendorId()).orElse(null);String uid=target;if(vv!=null&&target.equals(vv.getId()))uid=vv.getUserId();notifications.create(uid,"Service booking update",b.getBookingNumber()+" is now "+b.getStatus(),"SERVICE_BOOKING");return saved;}
 public ServiceBooking reschedule(String email,String id,RescheduleRequest r){ServiceBooking b=bookings.findById(id).orElseThrow();User u=user(email);if(!Objects.equals(u.getId(),b.getCustomerId())&&!u.getRoles().contains(User.Role.ADMIN))throw new IllegalArgumentException("Only the customer or admin can reschedule");if(!Set.of("REQUESTED","PROVIDER_CONFIRMED","CUSTOMER_CONFIRMED").contains(b.getStatus()))throw new IllegalArgumentException("Booking cannot be rescheduled in its current state");if(r.serviceDate()==null||r.startTime()==null||r.serviceDate().isBefore(LocalDate.now()))throw new IllegalArgumentException("Valid future date/time required");ServiceListing s=services.findById(b.getServiceId()).orElseThrow();ServiceListing.Package p=s.getPackages().stream().filter(x->Objects.equals(x.getId(),b.getPackageId())&&x.isActive()).findFirst().orElseThrow();LocalTime end=r.startTime().plusMinutes(p.getDurationMinutes());schedules.findByServiceIdAndDayOfWeekAndActiveTrue(s.getId(),r.serviceDate().getDayOfWeek()).stream().filter(x->!r.startTime().isBefore(x.getStartTime())&&!end.isAfter(x.getEndTime())).findFirst().orElseThrow(()->new IllegalArgumentException("Selected time is outside provider working hours"));List<String> blocking=List.of("REQUESTED","PROVIDER_CONFIRMED","CUSTOMER_CONFIRMED","PROVIDER_EN_ROUTE","SERVICE_STARTED","SERVICE_IN_PROGRESS");boolean conflict=bookings.findByServiceIdAndServiceDateAndStatusIn(s.getId(),r.serviceDate(),blocking).stream().filter(x->!Objects.equals(x.getId(),b.getId())).anyMatch(x->overlap(x.getStartTime(),x.getEndTime(),r.startTime(),end));if(conflict)throw new IllegalArgumentException("Selected slot is unavailable");b.setServiceDate(r.serviceDate());b.setStartTime(r.startTime());b.setEndTime(end);b.setStatus("RESCHEDULED");Instant now=Instant.now();b.getStatusHistory().add(entry("RESCHEDULED",u.getId(),r.note()==null?"Booking rescheduled":r.note(),now));b.setUpdatedAt(now);ServiceBooking saved=bookings.save(b);notifications.create(vendors.findById(b.getVendorId()).orElseThrow().getUserId(),"Service rescheduled",b.getBookingNumber()+" has been rescheduled.","SERVICE_BOOKING");return saved;}
 public ServiceBooking complete(String email,String id,CompletionRequest r){ServiceBooking b=bookings.findById(id).orElseThrow();Vendor v=vendor(email);if(!Objects.equals(v.getId(),b.getVendorId()))throw new IllegalArgumentException("Not your booking");if(!Set.of("SERVICE_STARTED","SERVICE_IN_PROGRESS","CUSTOMER_CONFIRMED","PROVIDER_EN_ROUTE").contains(b.getStatus()))throw new IllegalArgumentException("Booking is not ready for completion");b.setStatus("SERVICE_COMPLETED");Instant now=Instant.now();b.getStatusHistory().add(entry("SERVICE_COMPLETED",v.getUserId(),r.text(),now));if(r.text()!=null||r.proofUrl()!=null)b.getCompletionNotes().add(ServiceBooking.ProviderNote.builder().text(r.text()).proofUrl(r.proofUrl()).actorId(v.getUserId()).at(now).build());b.setUpdatedAt(now);ServiceBooking saved=bookings.save(b);notifications.create(b.getCustomerId(),"Service completed",b.getBookingNumber()+" has been marked completed.","SERVICE_BOOKING");return saved;}
 void validate(String a,String b){Map<String,Set<String>> m=Map.of("REQUESTED",Set.of("PROVIDER_CONFIRMED","REJECTED","CANCELLED"),"PROVIDER_CONFIRMED",Set.of("CUSTOMER_CONFIRMED","CANCELLED"),"CUSTOMER_CONFIRMED",Set.of("PROVIDER_EN_ROUTE","SERVICE_STARTED","CANCELLED","RESCHEDULED"),"PROVIDER_EN_ROUTE",Set.of("SERVICE_STARTED","NO_SHOW","CANCELLED"),"SERVICE_STARTED",Set.of("SERVICE_IN_PROGRESS","SERVICE_COMPLETED"),"SERVICE_IN_PROGRESS",Set.of("SERVICE_COMPLETED","DISPUTED"),"SERVICE_COMPLETED",Set.of("COMPLETED","DISPUTED"),"RESCHEDULE_REQUESTED",Set.of("RESCHEDULED","CANCELLED"));if(!a.equals(b)&&!m.getOrDefault(a,Set.of()).contains(b))throw new IllegalArgumentException("Invalid status transition: "+a+" -> "+b);}
 ServiceBooking.StatusEntry entry(String s,String a,String n,Instant t){return ServiceBooking.StatusEntry.builder().status(s).actorId(a).note(n).at(t).build();}User user(String e){return users.findByEmailIgnoreCase(e).orElseThrow();}Vendor vendor(String e){return vendors.findByUserId(user(e).getId()).orElseThrow(()->new IllegalArgumentException("Vendor profile not found"));}String req(String s,String m){if(s==null||s.isBlank())throw new IllegalArgumentException(m);return s.trim();}
}
